export const ORIGIN={lat:47.0245,lon:28.8323};
export function project(p){return [(p.lon-ORIGIN.lon)*111320*Math.cos(ORIGIN.lat*Math.PI/180),-(p.lat-ORIGIN.lat)*111320];}
export function area(r){let a=0;for(let i=0,j=r.length-1;i<r.length;j=i++)a+=r[j][0]*r[i][1]-r[i][0]*r[j][1];return Math.abs(a/2);}
export function metres(v){if(v==null)return NaN;let s=String(v).trim();let n=parseFloat(s.replace(',','.'));if(/ft|feet|'/.test(s))n*=.3048;return n;}
export function estimate(t,a){let h=metres(t.height),source='height',reason='OpenStreetMap height tag';const floors=parseFloat(t['building:levels']);if(!(h>0&&h<600)){if(floors>0&&floors<150){h=floors*3+(metres(t['roof:height'])||parseFloat(t['roof:levels'])*3||1.5);source='levels';reason='Mapped floors × 3 m + roof allowance';}else{source='estimate';const b=t.building;h=/apartments|residential|dormitory/.test(b)?(a>550?27:15):/industrial|warehouse|hangar/.test(b)?8:/garage|shed|kiosk|hut/.test(b)?3:/church|cathedral/.test(b)?18:/commercial|office|hotel|hospital/.test(b)?15:/house|detached|semidetached_house|terrace/.test(b)?(a>180?9:6):a<100?6:a<400?9:12;reason='Heuristic: building use and footprint area';}}
return {height:h,source,reason,floors:Number.isFinite(floors)?floors:null,minHeight:Math.max(0,Math.min(h-0.5,metres(t.min_height)||parseFloat(t['building:min_level'])*3||0))};}
function eq(a,b){return Math.abs(a.lat-b.lat)<1e-7&&Math.abs(a.lon-b.lon)<1e-7;}
function join(parts){let rings=[];parts=parts.filter(p=>p?.length>1).map(p=>[...p]);while(parts.length){let ring=parts.pop(),change=true;while(!eq(ring[0],ring.at(-1))&&change){change=false;for(let i=0;i<parts.length;i++){let p=parts[i];if(eq(ring.at(-1),p[0]))ring.push(...p.slice(1));else if(eq(ring.at(-1),p.at(-1)))ring.push(...p.slice(0,-1).reverse());else if(eq(ring[0],p.at(-1)))ring.unshift(...p.slice(0,-1));else if(eq(ring[0],p[0]))ring.unshift(...p.slice(1).reverse());else continue;parts.splice(i,1);change=true;break;}}if(eq(ring[0],ring.at(-1)))rings.push(ring);}return rings;}
export function inside(p,r){let c=false;for(let i=0,j=r.length-1;i<r.length;j=i++){const a=r[i],b=r[j];if((a[1]>p[1])!==(b[1]>p[1])&&p[0]<(b[0]-a[0])*(p[1]-a[1])/(b[1]-a[1])+a[0])c=!c;}return c;}
export function polygons(e){if(e.type==='way'){const r=e.geometry;if(!r||r.length<4||!eq(r[0],r.at(-1)))return [];return [{outer:r.map(project),holes:[]}];}const outer=join((e.members||[]).filter(m=>m.role!=='inner').map(m=>m.geometry)).map(r=>r.map(project));const inner=join((e.members||[]).filter(m=>m.role==='inner').map(m=>m.geometry)).map(r=>r.map(project));return outer.map(r=>({outer:r,holes:inner.filter(h=>inside(h[0],r))}));}
